<script>
 import {fontBookWindow,fontBookCapabilities} from './font-book-state.js';
 import {fontBookMenus} from './font-book-menus.js';
 import {fontCSSFamily,fontSourceAvailable,loadAvailableFonts} from './font-book-fonts.js';
 import {createLocalLibraryView} from './keychain-native-view.js';
 import './font-book.css';
 import './font-book-modern.css';
 let {window,state: fontBookState,profile,execute,registerView=()=>()=>{},available=true,active=true,fontGraph,getFile=()=>null}=$props();
 let root=$state(),failure=$state(''),renderError=$state(''),loadedIds=$state([]),characters=$state({}),collectionName=$state(''),collectionId=$state(''),duplicateMode=$state('skip');
 let session=$derived(fontBookWindow(fontBookState,window.id)),cap=$derived(fontBookCapabilities(profile)),selected=$derived(fontGraph?.fonts.find(f=>f.id===session?.selectedId)),collection=$derived(fontGraph?.collections.find(c=>c.id===session?.collectionId)),rows=$derived((fontGraph?.fonts??[]).filter(f=>(session?.source==='all'||session?.source==='user'&&f.location==='user'||session?.source==='bundled'&&f.location!=='user'||session?.source==='collection'&&collection?.fontIds.includes(f.id))&&[f.family,f.style,f.postscript].join(' ').toLowerCase().includes(session?.search.toLowerCase()??''))),duplicates=$derived((fontGraph?.fonts??[]).filter(f=>fontGraph.fonts.some(other=>other!==f&&other.postscript===f.postscript))),menus=$derived(fontBookMenus({session,selected,classic:cap.classic}));
 async function run(suffix,payload={}){if(!root?.isConnected||!available||!active)return;const mounted=root,originalSession=session,result=await execute(`fontbook.${suffix}`,{windowId:window.id},payload);if(root===mounted&&session===originalSession)failure=result?.status==='rejected'?result.error?.message??'Operation unavailable.':'';return result;}
 async function menu(item){if(!item.enabled||!item.request)return;await run('menu',{menu:null});await run(item.request.command.slice(9),item.request.payload);}
 $effect(()=>{if(!root||!session)return;const id=window.id,view=createLocalLibraryView({root,getRoot:()=>root,getSession:()=>fontBookWindow(fontBookState,id),available:()=>available&&active&&root?.isConnected===true});const unregister=registerView(id,view);return ()=>{view.dispose();if(typeof unregister==='function')unregister();else registerView(id,null,view);};});
 $effect(()=>{const graph=fontGraph,signature=JSON.stringify(graph);if(!graph||!root)return;for(const f of graph.fonts)if(f.fileId)JSON.stringify(getFile(f.fileId));let alive=true,loaded;loadedIds=[];characters={};renderError='';loadAvailableFonts(graph,{getFile,guard:()=>alive&&fontGraph===graph&&JSON.stringify(graph)===signature&&root?.isConnected===true}).then(result=>{if(!alive){result.dispose();return;}loaded=result;loadedIds=result.fonts.map(f=>f.id);characters=result.characters;renderError='';}).catch(error=>{if(alive){loadedIds=[];characters={};renderError=error.message;}});return ()=>{alive=false;loaded?.dispose();};});
 async function drop(event){event.preventDefault();let id=event.dataTransfer.getData('application/x-jesteros-file-id');if(!id){try{id=JSON.parse(event.dataTransfer.getData('application/x-jesteros-file-ids'))[0];}catch{}}if(id)await run('install',{fileId:id,duplicates:duplicateMode});}
</script>
{#if session&&fontGraph}<section bind:this={root} class="font-book-native" class:classic={cap.classic} class:win={cap.windows} class:golden={cap.golden} aria-label={cap.windows?'Font Library':'Font Book'} ondragover={event=>event.preventDefault()} ondrop={drop}>
 <nav class="font-menubar" aria-label="Application menus">{#each menus as m}<button class:active={session.menu===m.id} data-library-control={'menu-'+m.id} onclick={()=>run('menu',{menu:session.menu===m.id?null:m.id})}>{m.label}</button>{/each}</nav>{#if session.menu}<div class="font-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.children??[] as item}<button role="menuitem" disabled={!item.enabled} data-library-control={'action-'+item.label} onclick={()=>menu(item)}>{item.label}</button>{/each}</div>{/if}
 <header class="font-toolbar"><button data-library-control="install" onclick={()=>run('install',{duplicates:duplicateMode})}>＋</button><button data-library-control="information" disabled={!selected} onclick={()=>run('preview',{preview:'information'})}>ⓘ</button><div class="font-preview-switch">{#if cap.classic}{#each [['sample','Aa'],['repertoire','▦'],['custom','✎'],['information','i']] as p}<button data-library-control={'preview-'+p[0]} title={p[0]} class:active={session.preview===p[0]} onclick={()=>run('preview',{preview:p[0]})}>{p[1]}</button>{/each}{:else}{#each [['grid','▦'],['sample','Aa'],['list','☷']] as p}<button data-library-control={'view-'+p[0]} title={p[0]} class:active={session.view===p[0]} onclick={()=>run('preview',{view:p[0]})}>{p[1]}</button>{/each}{/if}</div><input data-library-control="search" type="search" aria-label="Search fonts" placeholder="Search" value={session.search} oninput={e=>run('navigate',{search:e.currentTarget.value})}/></header>
 <div class="font-workspace"><aside><h3>Fonts</h3>{#each [['all','All Fonts'],['user',cap.classic?'User':'My Fonts'],['bundled','Computer (local)']] as source}<button data-library-control={'source-'+source[0]} class:chosen={session.source===source[0]} onclick={()=>run('navigate',{source:source[0],collectionId:null})}>{source[1]}</button>{/each}<h3>Collections</h3>{#each fontGraph.collections as c}<button data-library-control={'collection-'+c.id} class:chosen={session.collectionId===c.id&&session.source==='collection'} onclick={()=>run('navigate',{source:'collection',collectionId:c.id})}>{c.name}</button>{/each}<button data-library-control="new-collection" onclick={()=>run('panel',{panel:'collection'})}>＋ New Collection</button></aside>
 <div class="font-list" class:gallery={!cap.classic&&session.view==='grid'} class:sample-list={!cap.classic&&session.view==='sample'}>{#each rows as font}<button data-library-control={'font-'+font.id} class:selected={selected===font} class:deactivated={!font.enabled} onclick={()=>run('navigate',{selectedId:font.id})} ondblclick={()=>run('preview',{preview:'repertoire'})}>{#if !cap.classic&&session.view!=='list'&&font.enabled&&loadedIds.includes(font.id)}<span class="font-card-specimen" style:font-family={fontCSSFamily(font)}>{session.view==='grid'?'Aa':session.sample}</span>{/if}<strong>{font.family}</strong><span>{font.style} {duplicates.includes(font)?'⚠':''}</span><small>{font.enabled?'':cap.classic?'Off':'Inactive'} {!fontSourceAvailable(font,getFile)?'Source unavailable':''}</small></button>{/each}{#if !rows.length}<p>No matching fonts.</p>{/if}</div>
 <main class="font-preview">{#if selected}<header><h2>{selected.family}</h2><span>{selected.style}</span></header>{#if session.preview==='information'}<dl>{#each [['PostScript name',selected.postscript],['Format',selected.format.toUpperCase()],['Source',selected.source==='bundled'?selected.bundledPath:'Files: '+selected.fileId],['Enabled',String(selected.enabled)],['Revision',selected.revision??'Bundled immutable bytes'],['SHA-256',selected.signature],['License',selected.license||'No license metadata in font; user must have redistribution rights.']] as pair}<dt>{pair[0]}</dt><dd>{pair[1]}</dd>{/each}</dl><p>Metadata and validation are local byte parsing, not host installation or operating-system certification.</p>
 {:else}{#if selected.enabled&&loadedIds.includes(selected.id)}{#if session.preview==='repertoire'}{#if characters[selected.id]}<div class="font-repertoire" style:font-family={fontCSSFamily(selected)} style:font-size={session.size+'px'}>{#each characters[selected.id] as code}<span title={'U+'+code.toString(16).toUpperCase().padStart(4,'0')}>{String.fromCodePoint(code)}</span>{/each}</div><p>Actual Unicode cmap mappings, up to 4096 characters.</p>{:else}<p>Repertoire parsing is unavailable for this compressed bundled WOFF2; sample preview still renders its genuine bytes.</p>{/if}{:else}<div class="font-specimen" style:font-family={fontCSSFamily(selected)} style:font-size={session.size+'px'}>{session.sample}</div>{/if}{:else}<p class="font-unavailable">{!selected.enabled?'This font is deactivated. Activate it to preview its genuine bytes.':renderError||'Loading original font bytes…'}</p>{/if}{#if !cap.classic}<div class="font-detail-preview-switch">{#each [['sample','Sample'],['repertoire','Repertoire'],['custom','Custom']] as p}<button data-library-control={'preview-'+p[0]} onclick={()=>run('preview',{preview:p[0]})}>{p[1]}</button>{/each}</div>{/if}{#if session.preview==='custom'}<textarea data-library-control="custom-text" aria-label="Custom preview text" value={session.sample} oninput={e=>run('preview',{sample:e.currentTarget.value})}></textarea>{/if}<label class="font-size">Size <input data-library-control="size" type="range" min="8" max="144" value={session.size} oninput={e=>run('preview',{size:Number(e.currentTarget.value)})}/><output>{session.size}</output></label>{/if}
 <div class="font-actions"><button data-library-control="toggle-font" onclick={()=>run('font',{operation:selected.enabled?'disable':'enable',fontId:selected.id})}>{selected.enabled?(cap.classic?'Disable':'Deactivate'):(cap.classic?'Enable':'Activate')}</button><button data-library-control="validate-font" onclick={()=>run('font',{operation:'validate',fontId:selected.id})}>Validate</button><button data-library-control="export-font" onclick={()=>run('font',{operation:'export',fontId:selected.id})}>Export…</button><button data-library-control="remove-font" onclick={()=>run('font',{operation:'remove',fontId:selected.id})}>Remove</button></div>
 {#if fontGraph.collections.length}<label>Add to collection<select data-library-control="collection-target" bind:value={collectionId}><option value="">Choose…</option>{#each fontGraph.collections as c}<option value={c.id}>{c.name}</option>{/each}</select></label><button data-library-control="add-to-collection" disabled={!collectionId} onclick={()=>run('collection',{operation:'add',collectionId,fontId:selected.id})}>Add</button>{/if}{#if collection}<button data-library-control="remove-from-collection" onclick={()=>run('collection',{operation:'remove',collectionId:collection.id,fontId:selected.id})}>Remove from “{collection.name}”</button>{/if}
 {:else}<p>Select a font to preview its actual bytes.</p>{/if}</main></div>
 <footer><span>{rows.length} fonts · {fontGraph.fonts.filter(f=>f.enabled).length} active</span><span role="status">{failure||session.status}</span></footer><details class="font-disclosure"><summary>Local fonts and version scope</summary><p>{cap.availability}</p><p>Liberation Sans and Inter Variable are distributable bundled fonts, not substitutes claimed to be licensed Apple system fonts. User installation supports genuine uncompressed TTF/OTF. Compressed WOFF2 is a bundled browser-rendered local extension. This does not install fonts on the host.</p></details>
 {#if session.panel!=='none'}<div class="font-sheet-backdrop"><section class="font-sheet" role="dialog" aria-modal="true" aria-label={session.panel}><header><h2>{session.panel==='preferences'?(cap.classic?'Font Book Preferences':'Font Book Settings'):session.panel==='collection'?'Collections':session.panel==='duplicates'?'Resolve Duplicates':'Font Validation'}</h2><button data-library-control="sheet-close" onclick={()=>run('panel',{panel:'none'})}>×</button></header>
 {#if session.panel==='preferences'}<p>{cap.availability}</p><label>Default install location (local graph)<select data-library-control="install-target" value={fontGraph.preferences.installTarget} onchange={e=>run('preferences',{installTarget:e.currentTarget.value})}><option value="user">User</option><option value="computer">Computer</option></select></label><label class="check"><input data-library-control="automatic-validation" type="checkbox" checked={fontGraph.preferences.automaticValidation} onchange={e=>run('preferences',{automaticValidation:e.currentTarget.checked})}/>Show automatic validation preference</label><p>Structural, bounds and checksum safety validation is always mandatory. The preference controls local workflow presentation, never bypasses parsing.</p><label>Duplicate installation<select data-library-control="duplicate-install" bind:value={duplicateMode}><option value="skip">Skip existing PostScript name</option><option value="keep">Keep Both</option><option value="replace">Replace active copy (deactivate old)</option></select></label>
 {:else if session.panel==='collection'}<label>New collection name<input data-library-control="collection-name" bind:value={collectionName}/></label><button data-library-control="create-collection" onclick={()=>run('collection',{operation:'create',name:collectionName})}>Create</button>{#each fontGraph.collections as c}<div class="collection-editor"><input data-library-control={'rename-'+c.id} aria-label={'Rename '+c.name} value={c.name} onchange={e=>run('collection',{operation:'rename',collectionId:c.id,name:e.currentTarget.value})}/><button data-library-control={'delete-'+c.id} onclick={()=>run('collection',{operation:'delete',collectionId:c.id})}>Delete Collection</button></div>{/each}
 {:else if session.panel==='duplicates'}{#if duplicates.length}<p>Choose the active copy to keep. Extra copies are deactivated, never fake-deleted from Files.</p>{#each duplicates as f}<button data-library-control={'keep-'+f.id} onclick={()=>run('duplicates',{keepId:f.id})}>Keep {f.family} · {f.fileId??'bundled'} · {f.enabled?'Active':'Inactive'}</button>{/each}<button data-library-control="resolve-all" onclick={()=>run('duplicates',{})}>Resolve Automatically</button>{:else}<p>No duplicate PostScript names.</p>{/if}
 {:else}<p>{session.status||'Select a font and choose Validate to inspect its real bytes.'}</p><p>TTF/OTF: SFNT signature, table bounds/non-overlap, table checksums, head magic, glyph count and name records. Bundled WOFF2: pinned SHA-256 and container header. This is not the complete operating-system font sanitizer.</p>{/if}
 {#if failure}<p role="alert" class="font-error">{failure}</p>{/if}</section></div>{/if}
</section>{/if}
